CREATE VIEW std_game_perspective AS WITH perspective_split AS (SELECT game_title, platform_name, main."trim"(perspective_value) AS perspective_value FROM std_inventory_game_ready , unnest(string_split(perspective_raw, ',')) AS t(perspective_value) WHERE (perspective_raw IS NOT NULL)), perspective_canonical AS (SELECT game_title, platform_name, CASE  WHEN (((perspective_value ~~* 'Bird view / Isometric') OR (perspective_value ~~* 'Bird view/Isometric'))) THEN ('Bird view/Isometric') WHEN ((perspective_value ~~* 'First person')) THEN ('First Person') WHEN ((perspective_value ~~* 'Side view')) THEN ('Side View') WHEN ((perspective_value ~~* 'Third person')) THEN ('Third Person') ELSE perspective_value END AS perspective_name FROM perspective_split)SELECT DISTINCT game_title, platform_name, perspective_name FROM perspective_canonical WHERE ((perspective_name IS NOT NULL) AND (perspective_name != ''));
